llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Pirfenidone, a 1-phenyl-2-pyridone structurally very close to the query's 1-phenylpyrazolone core, is rapidly absorbed with high oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil absolute oral bioavailability was 78% in healthy volunteers after an oral solution versus IV bolus, demonstrating high systemic availability for a related N-aryl heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron absolute oral bioavailability is approximately 60% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "DPP-4 inhibitors with N-aryl azole/pyrazolone-like scaffolds are well absorbed with oral bioavailability of 75–87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Alogliptin has absolute bioavailability of approximately 100% in healthy volunteers, showing that related N-aryl heterocyclic drugs can be essentially completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam absolute bioavailability is 92% in humans, supporting high F for a lipophilic N-heterocyclic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Trazodone absolute oral bioavailability averaged 91% in fasted men, supporting high F for an N-aryl heterocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone absolute oral bioavailability was about 60% in healthy subjects, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Acamprosate is poorly absorbed with about 11% bioavailability, but this reflects a small polar molecule with poor permeability and is not representative of the lipophilic N-aryl heterocycle query; it is contradictory evidence with limited applicability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is antipyrine, a lipophilic 1-phenylpyrazolone. Multiple high-transfer analogues with N-aryl heterocyclic structures show absolute oral bioavailability of 60–100% in humans, and the closest structural analogue pirfenidone is reported as high. The only low-bioavailability record (acamprosate, ~11%) is a small polar molecule with poor permeability and does not transfer to this scaffold. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for antipyrine itself is present in the supplied evidence; the prediction relies on close analogues.",
    "The acamprosate record has a mismatched SMILES/identity and low structural relevance, adding uncertainty to the contradictory evidence.",
    "Food and formulation effects are not uniformly controlled across the supporting records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

